		if (aNick.empty() || aNick.substr(0, 1) != "[") return aNick;

		auto x = aNick.find(']');
		// Avoid full deleting of [IMCOOL][CUSIHAVENOTHINGELSETHANBRACKETS]-type nicks
		if ((x != string::npos) && (aNick.substr(x + 1).length() > 0)) {
			return aNick.substr(x + 1);
		}

		return aNick;
	}

